import random, sys
from fractions import Fraction
sys.path.insert(0, "/tmp/tmp.WrTBAjmqLp")
from account import withdraw, Refused

def guarded_ok(b, a, L):
    try:
        withdraw(b, a, L); return True
    except Refused:
        return False

def exact_ok(b, a, L):
    # the claim: balance after withdrawal must not be below -L (exact arithmetic)
    return not (Fraction(b) - Fraction(a) < -Fraction(L))

random.seed(1)
found = []
for _ in range(300000):
    b = random.choice([random.uniform(-200, 200), round(random.uniform(-2, 2), 1)])
    a = random.choice([random.uniform(0.001, 300), round(random.uniform(0.1, 3), 1)])
    L = random.choice([random.uniform(0, 300), round(random.uniform(0, 3), 1)])
    if a <= 0:
        continue
    if guarded_ok(b, a, L) and not exact_ok(b, a, L):
        found.append(("accepted but exact says below floor", b, a, L))
    if not guarded_ok(b, a, L) and exact_ok(b, a, L):
        found.append(("refused but exact says allowed", b, a, L))
print("counterexamples:", len(found))
for f in found[:5]:
    print(f)
EOF
